// The native overlay table, generated by
// port/tools/gen_ovl_table.py from the overlay modules compiled natively (port/overlays.cmake).
#ifndef PORT_OVERLAY_NATIVE_H
#define PORT_OVERLAY_NATIVE_H

#include <stdint.h>

// A range of retail overlay bytes that the entry's hash covers.
typedef struct
{
    uint32_t addr;
    uint32_t size;
} PORT_OVL_RANGE;

typedef struct
{
    uint32_t addr;   // retail address of the function in its overlay
    uint32_t size;   // its size in bytes (the first range)
    uint64_t hash;   // FNV-1a 64 over the words of the ranges (gen_ovl_table.py)
    uint16_t range;  // first range in port_overlay_ranges
    uint16_t ranges; // number of ranges: the function, then any callees it needs to check
    uint16_t module; // index in port_overlay_modules
    void *native;
    const char *name;
} PORT_OVERLAY_NATIVE;

// Sorted by address (several modules may have an entry at one address).
extern const PORT_OVERLAY_NATIVE port_overlay_native_table[];
extern const int port_overlay_native_count;
extern const PORT_OVL_RANGE port_overlay_ranges[];
extern const char *const port_overlay_modules[];
// Lowest entry address and one word past the highest.
extern const uint32_t port_overlay_native_lo, port_overlay_native_hi;

// Prints the overlay call counters (native calls, interpreter entries, MIPS steps) to stderr.
void port_overlay_print_stats(void);

#endif
